// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var VW = 980, VH = 760;
draw.viewbox(0, 0, VW, VH);
draw.rect(VW, VH).fill('#ffffff');
var root = draw.group();

var TEAL = '#1f9aa0', TEAL_L = '#8fd8db', PURPLE = '#7b5ea7', PURPLE_L = '#c3b3e0';
var INK = '#151515', ORANGE = '#ee6a2e', GOLD = '#ffc21e';

var EV_NAMES = ['beginning event', 'mirror reflection', 'ending event'];
var st = { frame: 'astro', beta: 0.6, ev: 0 };

/* ---------- small drawing helpers ---------- */
function txt(g, s, x, y, size, color, anchor, bold) {
  var t = g.plain(String(s)).font({
    family: 'sans-serif', size: size, anchor: anchor || 'middle',
    weight: bold ? 'bold' : 'normal'
  }).fill(color || INK);
  t.attr({ x: x, y: y, 'dominant-baseline': 'middle' });
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3.2, 'stroke-linejoin': 'round' });
  return t;
}
function arrowHead(g, x, y, ang, color, size) {
  var a1 = ang + 2.7, a2 = ang - 2.7;
  g.polygon([x + ',' + y,
  (x + size * Math.cos(a1)) + ',' + (y + size * Math.sin(a1)),
  (x + size * Math.cos(a2)) + ',' + (y + size * Math.sin(a2))].join(' '))
    .fill(color).stroke('none');
}
function segArrow(g, x1, y1, x2, y2, color, w, op, frac) {
  var ln = g.line(x1, y1, x2, y2).stroke({ color: color, width: w, linecap: 'round' }).opacity(op);
  var f = (frac == null) ? 0.55 : frac;
  var hx = x1 + (x2 - x1) * f, hy = y1 + (y2 - y1) * f;
  var a = Math.atan2(y2 - y1, x2 - x1);
  if (Math.abs(x2 - x1) + Math.abs(y2 - y1) > 6) {
    var h = g.polygon('0,0').remove();
    arrowHead(g, hx, hy, a, color, Math.max(6, w * 3.4));
  }
  return ln;
}
function dimV(g, x, y1, y2, color, tick) {
  g.line(x, y1, x, y2).stroke({ color: color, width: 1.3 });
  arrowHead(g, x, y1, -Math.PI / 2, color, 7);
  arrowHead(g, x, y2, Math.PI / 2, color, 7);
  if (tick) {
    g.line(x - tick, y1, x + 4, y1).stroke({ color: color, width: 1 });
    g.line(x - tick, y2, x + 4, y2).stroke({ color: color, width: 1 });
  }
}
function dimH(g, x1, x2, y, color, tickTop) {
  g.line(x1, y, x2, y).stroke({ color: color, width: 1.3 });
  arrowHead(g, x1, y, Math.PI, color, 7);
  arrowHead(g, x2, y, 0, color, 7);
  if (tickTop != null) {
    g.line(x1, tickTop, x1, y + 6).stroke({ color: color, width: 1 });
    g.line(x2, tickTop, x2, y + 6).stroke({ color: color, width: 1 });
  }
}
function starburst(g, x, y, r) {
  var pts = [];
  for (var i = 0; i < 16; i++) {
    var a = i * Math.PI / 8, rr = (i % 2) ? r * 0.42 : r;
    pts.push((x + rr * Math.cos(a)).toFixed(1) + ',' + (y + rr * Math.sin(a)).toFixed(1));
  }
  return g.polygon(pts.join(' ')).fill('#ffd21e').stroke({ color: '#e8a400', width: 0.8 });
}
function glowDot(g, x, y, r) {
  g.circle(r * 3.6).center(x, y).fill(GOLD).opacity(0.28);
  g.circle(r * 2.2).center(x, y).fill('#ffb300').opacity(0.55);
  g.circle(r).center(x, y).fill('#fff3b8').stroke({ color: '#d99200', width: 1 });
}
function clockFace(g, x, y, r, frac, shade, dashed) {
  var c = g.circle(r * 2).center(x, y).fill('#ffffff')
    .stroke({ color: '#4a4f54', width: Math.max(1.1, r * 0.09) });
  if (dashed) c.attr('stroke-dasharray', '4,3');
  if (frac > 0) {
    var a0 = -Math.PI / 2, a1 = a0 + 2 * Math.PI * frac, ri = r * 0.86;
    var large = frac > 0.5 ? 1 : 0;
    g.path('M' + x + ',' + y + ' L' + (x + ri * Math.cos(a0)) + ',' + (y + ri * Math.sin(a0)) +
      ' A' + ri + ',' + ri + ' 0 ' + large + ' 1 ' + (x + ri * Math.cos(a1)) + ',' + (y + ri * Math.sin(a1)) + ' Z')
      .fill(shade || TEAL_L).opacity(0.85).stroke('none');
  }
  var ah = -Math.PI / 2 + 2 * Math.PI * frac;
  g.line(x, y, x + r * 0.62 * Math.cos(ah), y + r * 0.62 * Math.sin(ah))
    .stroke({ color: '#2b2f33', width: Math.max(1.1, r * 0.1), linecap: 'round' });
  g.circle(Math.max(2, r * 0.2)).center(x, y).fill('#2b2f33');
  return c;
}
function hov(el, tip, title, body) {
  el.css('cursor', 'pointer');
  el.on('mousemove', function (e) { showTooltip(tip, e); });
  el.on('mouseleave', function () { hideTooltip(); });
  if (title) el.on('click', function () { showPopup(title, body); });
}

