/* ---------- Panel (b) ---------- */
function drawPanelB(g, beta, gam) {
  var cabW = 86, cabH = 86, cabTop = 206, mirrorY = 217, srcY = 277;
  var Dpx = srcY - mirrorY;
  var Lpx = Dpx * gam * beta;
  if (Lpx > 182) Lpx = 182;
  var cxM = 716, xL = cxM - Lpx, xR = cxM + Lpx;

  function cabinAt(cx, active, showD) {
    var r = g.rect(cabW, cabH).move(cx - cabW / 2, cabTop).radius(11)
      .fill('#d7dcdf').opacity(active ? 0.95 : 0.55)
      .stroke({ color: active ? '#2f3438' : '#6b7379', width: 1.5 });
    r.attr('stroke-dasharray', '6,4');
    g.path('M' + (cx - cabW / 2 + 3) + ',' + (cabTop + 30) +
      ' q' + (cabW * 0.3) + ',-22 ' + (cabW * 0.6) + ',-4 q' + (cabW * 0.2) + ',12 ' + (cabW * 0.34) + ',2 L' +
      (cx + cabW / 2 - 3) + ',' + (cabTop + cabH - 4) + ' L' + (cx - cabW / 2 + 3) + ',' + (cabTop + cabH - 4) + ' Z')
      .fill('#c0c7cc').opacity(active ? 0.55 : 0.3).stroke('none');
    g.rect(28, 6).move(cx - 14, mirrorY - 3).fill(TEAL_L).stroke({ color: TEAL, width: 1.2 });
    starburst(g, cx - 20, srcY, 8);
    g.rect(16, 13).move(cx - 12, srcY - 6).radius(2).fill('#b9c0c6').stroke({ color: '#6b7379', width: 1 });
    clockFace(g, cx + 16, srcY, 8, 0.25, TEAL_L, true);
    if (showD) {
      dimV(g, cx + 34, mirrorY, srcY, INK, 0);
      txt(g, 'D', cx + 28, (mirrorY + srcY) / 2, 14, INK, 'end', true);
    }
    hov(r, 'The same cabin, photographed at one instant by the Earth observer.');
    return r;
  }

  cabinAt(xL, st.ev === 0, false);
  cabinAt(cxM, st.ev === 1, false);
  cabinAt(xR, st.ev === 2, true);

  /* diagonal light path */
  var P0 = [xL - 20, srcY], P1 = [cxM, mirrorY], P2 = [xR - 4, srcY];
  var o1 = (st.ev >= 1) ? 1 : 0.55, o2 = (st.ev >= 2) ? 1 : 0.55;
  var s1 = segArrow(g, P0[0], P0[1], P1[0], P1[1], PURPLE, 2.6, o1, 0.55);
  var s2 = segArrow(g, P1[0], P1[1], P2[0], P2[1], PURPLE, 2.6, o2, 0.55);
  hov(s1, 'Earth frame: the pulse travels the diagonal s, longer than D.',
    'Why the path is longer', 'Between emission and reflection the whole cabin slides forward, so the Earth observer sees the pulse move diagonally. Light still travels at c, so covering the longer distance s takes longer than covering D.');
  hov(s2, 'Second diagonal s: back down to the (now displaced) receiver.');
  txt(g, 's', (P0[0] + P1[0]) / 2 - 8, (P0[1] + P1[1]) / 2 - 14, 15, PURPLE, 'middle', true);
  txt(g, 's', (P1[0] + P2[0]) / 2 + 10, (P1[1] + P2[1]) / 2 - 14, 15, PURPLE, 'middle', true);

  /* L brackets */
  var bY = 320, tTop = cabTop + cabH + 4;
  dimH(g, xL, cxM, bY, INK, tTop);
  dimH(g, cxM, xR, bY, INK, tTop);
  txt(g, 'L = vΔt/2', (xL + cxM) / 2, bY - 12, 13, INK);
  txt(g, 'L', (cxM + xR) / 2, bY - 12, 13, INK);

  /* event labels */
  var spread = cxM - xL;
  var bx = (spread < 82) ? xL - 74 : xL;
  var ex = (spread < 82) ? xR + 74 : xR;
  txt(g, 'Beginning', bx, 352, 13, INK);
  txt(g, 'event', bx, 367, 13, INK);
  txt(g, 'Ending', ex, 352, 13, INK);
  txt(g, 'event', ex, 367, 13, INK);
  if (spread < 82) {
    g.line(bx + 34, 348, xL - 16, 300).stroke({ color: '#888', width: 1 });
    g.line(ex - 30, 348, xR + 16, 300).stroke({ color: '#888', width: 1 });
  }

  /* event glow markers */
  if (st.ev === 0) glowDot(g, P0[0], P0[1], 6);
  else if (st.ev === 1) glowDot(g, P1[0], P1[1], 6);
  else glowDot(g, P2[0], P2[1], 6);

  /* Earth ground + observer */
  g.polygon('530,455 966,455 934,500 498,500').fill('#e3dcc6');
  g.circle(18).center(690, 404).fill('#e8b98d').stroke({ color: '#b98c5e', width: 1 });
  g.path('M681,399 q9,-10 18,0').fill('none').stroke({ color: '#4a3a2a', width: 3 });
  g.rect(20, 27).move(680, 414).radius(5).fill('#5f7d4f');
  g.polyline('682,419 674,438').fill('none').stroke({ color: '#5f7d4f', width: 5, linecap: 'round' });
  g.polyline('698,419 706,436').fill('none').stroke({ color: '#5f7d4f', width: 5, linecap: 'round' });
  g.rect(7, 17).move(681, 440).fill('#6b6250');
  g.rect(7, 17).move(692, 440).fill('#6b6250');
  g.ellipse(12, 5).center(682, 457).fill('#2b3033');
  g.ellipse(12, 5).center(695, 457).fill('#2b3033');
  var eck = clockFace(g, 770, 420, 21, Math.min(0.95, 0.25 * gam), PURPLE_L, false);
  txt(g, 'Δt', 802, 420, 16, PURPLE, 'middle', true);
  hov(eck, 'Earth clock: Δt = γΔτ — more time elapses than on the shuttle clock.');
  txt(g, 'Observer on Earth', 566, 472, 13, INK);
  g.path('M628,468 q22,-8 42,-24').fill('none').stroke({ color: INK, width: 1.3 });
  arrowHead(g, 674, 441, -0.7, INK, 7);

  txt(g, '(b)', 716, 526, 15, INK);
}

/* ---------- Panel (c) ---------- */
function drawPanelC(g, beta, gam) {
  var cx = 400, baseY = 690, Dt = 86;
  var Lt = Dt * gam * beta;
  if (Lt > 258) Lt = 258;
  var ax = cx, ay = baseY - Dt;

  g.line(cx - Lt, baseY, cx + Lt, baseY).stroke({ color: INK, width: 2 });
  g.line(cx, baseY, ax, ay).stroke({ color: INK, width: 1.6 });

  var o1 = (st.ev >= 1) ? 1 : 0.55, o2 = (st.ev >= 2) ? 1 : 0.55;
  var l1 = segArrow(g, cx - Lt, baseY, ax, ay, PURPLE, 2.6, o1, 0.55);
  var l2 = segArrow(g, ax, ay, cx + Lt, baseY, PURPLE, 2.6, o2, 0.55);
  var tipC = 'Each slanted side is s = √(D² + L²): the Earth-frame light path for half the trip.';
  hov(l1, tipC, 'Pythagoras gives time dilation',
    'The Earth observer measures c·(Δt/2) = s = √(D² + L²) with L = vΔt/2, while the astronaut measures c·(Δτ/2) = D. Eliminating D gives Δt = Δτ/√(1 − v²/c²) = γΔτ.');
  hov(l2, tipC, 'Pythagoras gives time dilation',
    'The Earth observer measures c·(Δt/2) = s = √(D² + L²) with L = vΔt/2, while the astronaut measures c·(Δτ/2) = D. Eliminating D gives Δt = Δτ/√(1 − v²/c²) = γΔτ.');

  txt(g, 's', cx - Lt / 2 - 12, (baseY + ay) / 2 - 12, 15, PURPLE, 'middle', true);
  txt(g, 's', cx + Lt / 2 + 12, (baseY + ay) / 2 - 12, 15, PURPLE, 'middle', true);
  txt(g, 'D', cx + 12, (baseY + ay) / 2, 15, INK, 'start', true);
  txt(g, 's = √(D² + L²)', cx + 34, ay - 16, 16, INK, 'start');

  var lx1 = cx - Math.max(Lt / 2, 62), lx2 = cx + Math.max(Lt / 2, 34);
  txt(g, 'L = vΔt/2', lx1, baseY + 20, 14, INK);
  txt(g, 'L', lx2, baseY + 20, 14, INK);

  if (st.ev === 0) glowDot(g, cx - Lt, baseY, 6);
  else if (st.ev === 1) glowDot(g, ax, ay, 6);
  else glowDot(g, cx + Lt, baseY, 6);

  txt(g, '(c)', cx, baseY + 46, 15, INK);
}

/* ---------- readout ---------- */
function drawReadout(g, beta, gam, dtau, dt) {
  var x = 712, y = 584, w = 240, h = 116;
  var box = g.rect(w, h).move(x, y).radius(8).fill('#fbfbfc').stroke({ color: '#c8ccd0', width: 1.2 });
  hov(box, 'Δt = γΔτ, with γ = 1/√(1 − v²/c²).',
    'The Lorentz factor', 'γ = 1/√(1 − v²/c²) is exactly the ratio of the diagonal path 2s to the vertical path 2D. At v = 0 it is 1 and both clocks agree; as v → c it grows without bound.');
  txt(g, 'v / c = ' + beta.toFixed(2), x + 16, y + 24, 14, INK, 'start');
  txt(g, 'Δτ = ' + dtau.toFixed(2) + ' ns  (shuttle clock)', x + 16, y + 49, 13, TEAL, 'start');
  txt(g, 'Δt = ' + dt.toFixed(2) + ' ns  (Earth clock)', x + 16, y + 73, 13, PURPLE, 'start');
  txt(g, 'γ = Δt / Δτ = ' + gam.toFixed(3), x + 16, y + 97, 14, INK, 'start', true);
}

/* ---------- render ---------- */
function render() {
  root.clear();
  var beta = st.beta;
  var gam = 1 / Math.sqrt(1 - beta * beta);
  var dtau = 10.0, dt = dtau * gam;

  var gA = root.group(), gB = root.group(), gC = root.group(), gR = root.group();
  drawPanelA(gA);
  drawPanelB(gB, beta, gam);
  drawPanelC(gC, beta, gam);
  drawReadout(gR, beta, gam, dtau, dt);

  gA.opacity(st.frame === 'earth' ? 0.15 : 1);
  gB.opacity(st.frame === 'astro' ? 0.15 : 1);
  gC.opacity(st.frame === 'astro' ? 0.15 : 1);
}

