function segArrow(g, x1, y1, x2, y2, color, w, op, frac) {
  var ln = g.line(x1, y1, x2, y2).stroke({ color: color, width: w, linecap: 'round' }).opacity(op);
  var f = (frac == null) ? 0.55 : frac;
  var hx = x1 + (x2 - x1) * f, hy = y1 + (y2 - y1) * f;
