// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var VW = 780, VH = 660;
draw.viewbox(0, 0, VW, VH);
draw.rect(VW, VH).fill('#ffffff');
var root = draw.group();

var TEAL = '#1f9aa0', TEAL_L = '#8fd8db', PURPLE = '#7b5ea7', PURPLE_L = '#c3b3e0';
var INK = '#151515', ORANGE = '#ee6a2e', GOLD = '#ffc21e';

var EV_NAMES = ['beginning event', 'mirror reflection', 'ending event'];
var st = { frame: 'astro', beta: 0.85, ev: 0 };

/* ---------- drawing helpers ---------- */
function txt(g, s, x, y, size, color, anchor, bold) {
  var t = g.plain(String(s)).font({
    family: 'sans-serif', size: size, anchor: anchor || 'middle',
    weight: bold ? 'bold' : 'normal'
  }).fill(color || INK);
  t.attr({ x: x, y: y, 'dominant-baseline': 'middle' });
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 3.6, 'stroke-linejoin': 'round' });
  return t;
}
function arrowHead(g, x, y, ang, color, size) {
  var a1 = ang + 2.7, a2 = ang - 2.7;
  g.polygon([x + ',' + y,
  (x + size * Math.cos(a1)) + ',' + (y + size * Math.sin(a1)),
  (x + size * Math.cos(a2)) + ',' + (y + size * Math.sin(a2))].join(' '))
    .fill(color).stroke('none');
}
function segArrow(g, x1, y1, x2, y2, color, w, op, frac) {
  var ln = g.line(x1, y1, x2, y2).stroke({ color: color, width: w, linecap: 'round' }).opacity(op);
  var f = (frac == null) ? 0.55 : frac;
  var hx = x1 + (x2 - x1) * f, hy = y1 + (y2 - y1) * f;
  var a = Math.atan2(y2 - y1, x2 - x1);
  if (Math.abs(x2 - x1) + Math.abs(y2 - y1) > 8) arrowHead(g, hx, hy, a, color, Math.max(7, w * 3.4));
  return ln;
}
function dimV(g, x, y1, y2, color, tick) {
  g.line(x, y1, x, y2).stroke({ color: color, width: 1.4 });
  arrowHead(g, x, y1, -Math.PI / 2, color, 7.5);
  arrowHead(g, x, y2, Math.PI / 2, color, 7.5);
  if (tick) {
    g.line(x - tick, y1, x + 5, y1).stroke({ color: color, width: 1.1 });
    g.line(x - tick, y2, x + 5, y2).stroke({ color: color, width: 1.1 });
  }
}
function dimH(g, x1, x2, y, color, tickTop) {
  g.line(x1, y, x2, y).stroke({ color: color, width: 1.4 });
  arrowHead(g, x1, y, Math.PI, color, 7.5);
  arrowHead(g, x2, y, 0, color, 7.5);
  if (tickTop != null) {
    g.line(x1, tickTop, x1, y + 7).stroke({ color: color, width: 1.1 });
    g.line(x2, tickTop, x2, y + 7).stroke({ color: color, width: 1.1 });
  }
}
function starburst(g, x, y, r) {
