  cabinAt(xL, st.ev === 0, false);
  cabinAt(CXM, st.ev === 1, false);
  cabinAt(xR, st.ev === 2, true);

  /* diagonal light path */
  var P0 = [xL - 22, SRC_Y], P1 = [CXM, MIR_Y], P2 = [xR - 22, SRC_Y];
  var o1 = (st.ev >= 1) ? 1 : 0.55, o2 = (st.ev >= 2) ? 1 : 0.55;
  var s1 = segArrow(g, P0[0], P0[1], P1[0], P1[1], PURPLE, 2.8, o1, 0.55);
  var s2 = segArrow(g, P1[0], P1[1], P2[0], P2[1], PURPLE, 2.8, o2, 0.55);
  hov(s1, 'Earth frame: the pulse travels the diagonal s, longer than D.',
    'Why the path is longer', 'Between emission and reflection the whole cabin slides forward, so the Earth observer sees the pulse move diagonally. Light still travels at c, so covering the longer distance s must take longer than covering D.');
  hov(s2, 'Second diagonal s: back down to the (now displaced) receiver.',
    'Why the path is longer', 'Between reflection and reception the cabin keeps moving, so the return leg is also a diagonal of length s. The Earth observer clocks 2s/c while the astronaut clocks 2D/c.');
  txt(g, 's', (P0[0] + P1[0]) / 2 - 4, (P0[1] + P1[1]) / 2 - 17, 18, PURPLE, 'middle', true);
  txt(g, 's', (P1[0] + P2[0]) / 2 + 6, (P1[1] + P2[1]) / 2 - 17, 18, PURPLE, 'middle', true);

  /* L brackets */
  var bY = 178;
  dimH(g, xL, CXM, bY, INK, CAB_TOP + CAB_H + 4);
  dimH(g, CXM, xR, bY, INK, CAB_TOP + CAB_H + 4);
  txt(g, 'L = vΔt/2', (xL + CXM) / 2, 165, 15, INK);
  txt(g, 'L', (CXM + xR) / 2, 165, 17, INK, 'middle', true);

  /* event labels */
  txt(g, 'Beginning', xL, 202, 14, INK);
  txt(g, 'event', xL, 219, 14, INK);
  txt(g, 'Ending', xR, 202, 14, INK);
  txt(g, 'event', xR, 219, 14, INK);

  /* event glow markers */
  if (st.ev === 0) glowDot(g, P0[0], P0[1], 6);
  else if (st.ev === 1) glowDot(g, P1[0], P1[1], 6);
  else glowDot(g, P2[0], P2[1], 6);

  /* Earth ground + observer */
  g.polygon('392,300 776,300 748,352 364,352').fill('#e3dcc6');
  g.circle(20).center(600, 246).fill('#e8b98d').stroke({ color: '#b98c5e', width: 1 });
  g.path('M591,241 q9,-10 18,0').fill('none').stroke({ color: '#4a3a2a', width: 3 });
  g.rect(20, 28).move(590, 257).radius(5).fill('#5f7d4f');
  g.polyline('592,262 583,282').fill('none').stroke({ color: '#5f7d4f', width: 5, linecap: 'round' });
  g.polyline('608,262 617,280').fill('none').stroke({ color: '#5f7d4f', width: 5, linecap: 'round' });
  g.rect(7, 18).move(591, 284).fill('#6b6250');
  g.rect(7, 18).move(602, 284).fill('#6b6250');
  g.ellipse(12, 5).center(592, 302).fill('#2b3033');
  g.ellipse(12, 5).center(605, 302).fill('#2b3033');
  var eck = clockFace(g, 668, 272, 21, Math.min(0.96, 0.25 * gam), PURPLE_L, false);
  txt(g, 'Δt', 700, 272, 18, PURPLE, 'middle', true);
  hov(eck, 'Earth clock: Δt = γΔτ — more time elapses than on the shuttle clock.');
  txt(g, 'Observer', 452, 316, 14, INK);
  txt(g, 'on Earth', 452, 333, 14, INK);
  g.path('M492,320 q30,-6 52,-24').fill('none').stroke({ color: INK, width: 1.4 });
  arrowHead(g, 548, 292, -0.62, INK, 7);

  txt(g, '(b)', 572, 382, 18, INK);
}

/* ---------- Panel (c) ---------- */
function drawPanelC(g, beta, gam) {
  var cx = 225, baseY = 596, Dt = 78, LtMax = 190;
  var Lt = Dt * gam * beta;
  if (Lt > LtMax) { Dt = Dt * (LtMax / Lt); Lt = LtMax; }
  var ay = baseY - Dt;

  g.line(cx - Lt, baseY, cx + Lt, baseY).stroke({ color: INK, width: 2.2 });
  g.line(cx, baseY, cx, ay).stroke({ color: INK, width: 1.8 });

  var o1 = (st.ev >= 1) ? 1 : 0.55, o2 = (st.ev >= 2) ? 1 : 0.55;
  var pop = 'Pythagoras gives time dilation';
  var pbody = 'The Earth observer measures c·(Δt/2) = s = √(D² + L²) with L = vΔt/2, while the astronaut measures c·(Δτ/2) = D. Eliminating D gives Δt = Δτ/√(1 − v²/c²) = γΔτ.';
  var l1 = segArrow(g, cx - Lt, baseY, cx, ay, PURPLE, 2.8, o1, 0.55);
  var l2 = segArrow(g, cx, ay, cx + Lt, baseY, PURPLE, 2.8, o2, 0.55);
  var tipC = 'Each slanted side is s = √(D² + L²): the Earth-frame light path for half the trip.';
  hov(l1, tipC, pop, pbody);
  hov(l2, tipC, pop, pbody);

  txt(g, 's', cx - Lt / 2 - 14, (baseY + ay) / 2 - 13, 18, PURPLE, 'middle', true);
  txt(g, 's', cx + Lt / 2 + 14, (baseY + ay) / 2 - 13, 18, PURPLE, 'middle', true);
  txt(g, 'D', cx + 13, (baseY + ay) / 2, 18, INK, 'start', true);
  txt(g, 's = √(D² + L²)', cx + 46, ay - 22, 18, INK, 'start');

  var lx1 = cx - Math.max(Lt / 2, 60), lx2 = cx + Math.max(Lt / 2, 32);
  txt(g, 'L = vΔt/2', lx1, baseY + 22, 16, INK);
  txt(g, 'L', lx2, baseY + 22, 17, INK, 'middle', true);

  if (st.ev === 0) glowDot(g, cx - Lt, baseY, 6);
  else if (st.ev === 1) glowDot(g, cx, ay, 6);
  else glowDot(g, cx + Lt, baseY, 6);

  txt(g, '(c)', cx, baseY + 50, 18, INK);
}

/* ---------- readout ---------- */
function drawReadout(g, beta, gam, dtau, dt) {
  var x = 478, y = 436, w = 284, h = 132;
  var box = g.rect(w, h).move(x, y).radius(9).fill('#fbfbfc').stroke({ color: '#c8ccd0', width: 1.3 });
  hov(box, 'Δt = γΔτ, with γ = 1/√(1 − v²/c²).',
    'The Lorentz factor', 'γ = 1/√(1 − v²/c²) is exactly the ratio of the diagonal path 2s to the vertical path 2D. At v = 0 it equals 1 and both clocks agree; as v → c it grows without bound.');
  txt(g, 'v / c = ' + beta.toFixed(2), x + 18, y + 26, 16, INK, 'start');
  txt(g, 'Δτ = ' + dtau.toFixed(2) + ' ns  (shuttle clock)', x + 18, y + 55, 15, TEAL, 'start');
  txt(g, 'Δt = ' + dt.toFixed(2) + ' ns  (Earth clock)', x + 18, y + 82, 15, PURPLE, 'start');
  txt(g, 'γ = Δt / Δτ = ' + gam.toFixed(3), x + 18, y + 110, 16, INK, 'start', true);
}

/* ---------- highlight cards (frame toggle: highlight, never hide) ---------- */
function drawCards(g) {
  var a = (st.frame === 'astro' || st.frame === 'both');
  var e = (st.frame === 'earth' || st.frame === 'both');
  if (a) {
    g.rect(358, 420).move(4, 6).radius(16).fill(TEAL).opacity(0.10);
    g.rect(358, 420).move(4, 6).radius(16).fill('none').stroke({ color: TEAL, width: 1.6, opacity: 0.55 });
  }
  if (e) {
    g.rect(412, 392).move(364, 6).radius(16).fill(PURPLE).opacity(0.09);
    g.rect(412, 392).move(364, 6).radius(16).fill('none').stroke({ color: PURPLE, width: 1.6, opacity: 0.5 });
    g.rect(436, 226).move(12, 424).radius(16).fill(PURPLE).opacity(0.09);
    g.rect(436, 226).move(12, 424).radius(16).fill('none').stroke({ color: PURPLE, width: 1.6, opacity: 0.5 });
  }
}

/* ---------- render ---------- */
function render() {
  root.clear();
  var beta = st.beta;
  var gam = 1 / Math.sqrt(1 - beta * beta);
  var dtau = 10.0, dt = dtau * gam;

  drawCards(root.group());
  drawPanelA(root.group());
  drawPanelB(root.group(), beta, gam);
  drawPanelC(root.group(), beta, gam);
  drawReadout(root.group(), beta, gam, dtau, dt);
}

/* ---------- interaction handlers ---------- */
function toggle_frameToggle(v) { st.frame = v; render(); }
function update_speed(v) { st.beta = +v; render(); }
function updateEventLabel() {
  var el = document.getElementById('eventStateLabel');
  if (el) el.textContent = EV_NAMES[st.ev];
}
function trigger_eventStep() { st.ev = (st.ev + 1) % 3; updateEventLabel(); render(); }
function trigger_keyInsight() {
  showPopup('Key insight',
    'If light must travel at c for both observers, then a longer light path can only mean a longer elapsed time — the Earth observer\u2019s diagonal hypotenuse is literally the extra time the moving clock "loses". Both observers agree on the three events; they disagree only about the length of the path that joins them.');
}

/* ---------- demo steps ---------- */
var STEPS = [
  {
    title: 'The light clock at rest', frame: 'astro', beta: 0.85, ev: 0,
    narr: 'Inside the shuttle the astronaut sees the pulse go straight up to the mirror and straight back down, covering 2D. The onboard clock reads the proper time Δτ = 2D/c.'
  },
  {
    title: 'Same events, Earth frame', frame: 'earth', beta: 0.85, ev: 0,
    narr: 'Switch the highlight to the Earth observer: the cabin has moved between emission and reception, so the identical pulse traces two diagonal segments s — a path unmistakably longer than 2D.'
  },
  {
    title: 'Walk the pulse through the three events', frame: 'earth', beta: 0.85, ev: 1,
    narr: 'Step from emission to reflection to reception. Each event lights up in the cabin snapshots and at the matching vertex of the triangle — both observers see exactly these three events.'
  },
  {
    title: 'The ending event and the triangle', frame: 'earth', beta: 0.85, ev: 2,
    narr: 'At reception the diagonal path closes into the isosceles triangle with altitude D and base halves L = vΔt/2, so s = √(D² + L²).'
  },
  {
    title: 'Slow the shuttle down', frame: 'both', beta: 0.1, ev: 2,
    narr: 'At low speed L nearly vanishes, the triangle flattens toward a vertical line, and Δt collapses onto Δτ — the classical limit where everyone agrees on time.'
  },
  {
    title: 'Push toward the speed of light', frame: 'both', beta: 0.92, ev: 2,
    narr: 'Crank v up: the snapshots slide apart, s grows far beyond D, and Δt balloons relative to Δτ by the factor γ = 1/√(1 − v²/c²).'
  }
];
var curStep = 0;
function applyStep(i) {
  curStep = (i + STEPS.length) % STEPS.length;
  var s = STEPS[curStep];
  st.frame = s.frame; st.beta = s.beta; st.ev = s.ev;
  var fi = document.getElementById('frameToggleInput');
  if (fi) fi.value = s.frame;
  var si = document.getElementById('speedInput');
  if (si) si.value = s.beta;
  var sv = document.getElementById('speedVal');
  if (sv) sv.value = s.beta.toFixed(2);
  updateEventLabel();
  document.getElementById('demoTitle').textContent = (curStep + 1) + '. ' + s.title;
  document.getElementById('demoNarration').textContent = s.narr;
  document.getElementById('stepLabel').textContent = 'Step ' + (curStep + 1) + ' / ' + STEPS.length;
  render();
}
function nextStep() { applyStep(curStep + 1); }
function prevStep() { applyStep(curStep - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

