    r.attr('stroke-dasharray', '6,4');
    cg.path('M' + (cx - CAB_W / 2 + 3) + ',' + (CAB_TOP + 30) +
      ' q' + (CAB_W * 0.3) + ',-22 ' + (CAB_W * 0.6) + ',-4 q' + (CAB_W * 0.2) + ',12 ' + (CAB_W * 0.34) + ',2 L' +
      (cx + CAB_W / 2 - 3) + ',' + (CAB_TOP + CAB_H - 4) + ' L' + (cx - CAB_W / 2 + 3) + ',' + (CAB_TOP + CAB_H - 4) + ' Z')
