    return cg;
  }

  cabinAt(xL, st.ev === 0, dupOp);
  cabinAt(xR, st.ev === 2, dupOp);
  cabinAt(CXM, st.ev === 1, 1);

  /* D dimension (drawn on the right snapshot, always legible) */
  dimV(g, xR + 28, MIR_Y, SRC_Y, INK, 0, 1);
