/* ---------- Panel (c) ---------- */
function drawPanelC(g, beta, gam) {
  var cx = 390, baseY = 632, Dt = 122, LtMax = 262;
  var Lt = Dt * gam * beta;
  if (Lt > LtMax) { Dt = Dt * (LtMax / Lt); Lt = LtMax; }
  var ay = baseY - Dt;

  g.line(cx - Lt, baseY, cx + Lt, baseY).stroke({ color: INK, width: 2.4 });
  g.line(cx, baseY, cx, ay).stroke({ color: INK, width: 2 });

  var o1 = (st.ev >= 1) ? 1 : 0.5, o2 = (st.ev >= 2) ? 1 : 0.5;
  var pop = 'Pythagoras gives time dilation';
  var pbody = 'The Earth observer measures c·(Δt/2) = s = √(D² + L²) with L = vΔt/2, while the astronaut measures c·(Δτ/2) = D. Eliminating D gives Δt = Δτ/√(1 − v²/c²) = γΔτ.';
  var l1 = segArrow(g, cx - Lt, baseY, cx, ay, PURPLE, 3, o1, 0.55);
  var l2 = segArrow(g, cx, ay, cx + Lt, baseY, PURPLE, 3, o2, 0.55);
  var tipC = 'Each slanted side is s = √(D² + L²): the Earth-frame light path for half the trip.';
  hov(l1, tipC, pop, pbody);
  hov(l2, tipC, pop, pbody);

  if (Lt > 30) {
    txt(g, 's', cx - Lt / 2 - 16, (baseY + ay) / 2 - 14, 21, PURPLE, 'middle', true);
    txt(g, 's', cx + Lt / 2 + 16, (baseY + ay) / 2 - 14, 21, PURPLE, 'middle', true);
  }
  txt(g, 'D', cx + 15, (baseY + ay) / 2, 21, INK, 'start', true);
  txt(g, 's = √(D² + L²)', cx + 58, ay - 20, 20, INK, 'start');
  g.path('M' + (cx + 52) + ',' + (ay - 14) + ' q-18,4 -34,10').fill('none')
    .stroke({ color: '#9aa0a6', width: 1.1 });

  if (Lt >= 70) {
    txt(g, 'L = vΔt/2', cx - Lt / 2, baseY + 28, 18, INK);
    txt(g, 'L', cx + Lt / 2, baseY + 28, 20, INK, 'middle', true);
  } else {
    txt(g, 'L = vΔt/2 ≈ 0', cx, baseY + 28, 18, INK);
  }

  if (st.ev === 0) vertexMark(g, cx - Lt, baseY);
  else if (st.ev === 1) vertexMark(g, cx, ay);
  else vertexMark(g, cx + Lt, baseY);

  txt(g, '(c)', cx, baseY + 58, 20, INK, 'middle', true);
}

