  a.textContent = 'v / c = ' + beta.toFixed(2);
  document.getElementById('roTau').textContent = 'Δτ = ' + dtau.toFixed(2) + ' ns (shuttle clock)';
  document.getElementById('roDt').textContent = 'Δt = ' + dt.toFixed(2) + ' ns (Earth clock)';
  document.getElementById('roGam').textContent = 'γ = Δt / Δτ = ' + gam.toFixed(3);
}

/* ---------- render ---------- */
function render() {
  root.clear();
  var beta = st.beta;
  var gam = 1 / Math.sqrt(1 - beta * beta);
  var dtau = 10.0, dt = dtau * gam;

  drawCards(root.group());
  drawPanelA(root.group());
  drawPanelB(root.group(), beta, gam);
  drawPanelC(root.group(), beta, gam);
  updateReadout(beta, gam, dtau, dt);
}

